def L(e): return sp.latex(e).replace(r'\\frac', r'\\dfrac')

C = []

def uniq(correct, cands, k_=3):
    out = [correct]
    for c_ in cands:
        if c_ not in out: out.append(c_)
        if len(out) == k_ + 1: break
    assert len(out) == k_ + 1, ('wrongs', correct)
    return out[1:]

def with_img(q_, s_): q_['img'] = s_; return q_

